{
  "doc_id": "1225291749",
  "stock_code": "000789",
  "stock_name": "万年青",
  "market": "szse",
  "publish_date": "2026-05-11",
  "announcement_title": "关于江西万年青水泥股份有限公司收到江西证监局行政监管措施决定书及深圳证券交易所监管函的临时受托管理事务报告",
  "doc_type": "regulatory_measure",
  "regulator_name": {
    "value": "中国证券监督管理委员会江西监管局、深圳证券交易所",
    "evidence": {
      "evidence_text": "发行人收到中国证券监督管理委员会江西监管局下发的《关于对江西万年青水泥股份有限公司采取责令改正措施并对李世锋、熊汉南采取出具警示函措施的决定》（〔2026〕1号），以及深圳证券交易所下发的《关于对江西万年青水泥股份有限公司、李世锋、熊汉南的监管函》（公司部监管函〔2026〕第8号）。",
      "page_no": 3
    }
  },
  "targets": [
    {
      "name": "江西万年青水泥股份有限公司",
      "role": "发行人",
      "target_type": "listed_company",
      "evidence": {
        "evidence_text": "中信建投证券作为江西万年青水泥股份有限公司2025年面向专业投资者公开发行公司债券（第一期）（债券代码：524330.SZ，债券简称：25江泥01）的受托管理人",
        "page_no": 3
      }
    },
    {
      "name": "李世锋",
      "role": "时任总经理",
      "target_type": "executive",
      "evidence": {
        "evidence_text": "对时任总经理李世锋、财务总监兼董事会秘书（代行）熊汉南采取出具警示函的行政监管措施。",
        "page_no": 3
      }
    },
    {
      "name": "熊汉南",
      "role": "财务总监兼董事会秘书（代行）",
      "target_type": "executive",
      "evidence": {
        "evidence_text": "对时任总经理李世锋、财务总监兼董事会秘书（代行）熊汉南采取出具警示函的行政监管措施。",
        "page_no": 3
      }
    },
    {
      "name": "中信建投证券股份有限公司",
      "role": "受托管理人",
      "target_type": "intermediary",
      "evidence": {
        "evidence_text": "中信建投证券作为上述存续债券的受托管理人，为充分保障债券投资人的利益，履行债券受托管理人职责，在获悉相关事项后，及时与发行人进行了沟通，根据《公司债券受托管理人执业行为准则》的有关规定出具本临时受托管理事务报告。",
        "page_no": 4
      }
    }
  ],
  "issues": [
    {
      "issue_type": "internal_control",
      "issue_summary": "董事会秘书长期空缺",
      "is_violation_related": true,
      "evidence": {
        "evidence_text": "一是董事会秘书长期空缺。自2023年1月至今，一直由副总经理代行董事会秘书职责。",
        "page_no": 3
      }
    },
    {
      "issue_type": "financial_irregularity",
      "issue_summary": "贸易业务财务核算不规范，部分贸易业务收入核算方法不当导致年度报告收入成本披露不准确",
      "is_violation_related": true,
      "evidence": {
        "evidence_text": "二是贸易业务财务核算不规范。公司对部分应按照净额法核算收入的贸易业务采用总额法核算，导致2024年年度报告中收入成本披露不准确。",
        "page_no": 3
      }
    },
    {
      "issue_type": "information_disclosure",
      "issue_summary": "主要客户情况披露不准确，部分客户收入统计不准确且未合并列示同一控制人控制的客户",
      "is_violation_related": true,
      "evidence": {
        "evidence_text": "三是主要客户情况披露不准确。公司部分客户收入统计不准确且未将同一控制人控制的客户合并列示。",
        "page_no": 3
      }
    },
    {
      "issue_type": "information_disclosure",
      "issue_summary": "货币资金权利受限信息披露不完整及现金流量表披露不准确",
      "is_violation_related": true,
      "evidence": {
        "evidence_text": "四是货币资金权利受限信息披露不完整及现金流量表披露不准确。公司未将部分银行承兑汇票保证金、部分受限货币资金账户纳入统计范围。",
        "page_no": 3
      }
    }
  ],
  "actions": [
    {
      "action_type": "order_correction",
      "action_source_type": "regulator_required",
      "deadline": null,
      "required_disclosure": null,
      "evidence": {
        "evidence_text": "江西证监局认为，发行人上述行为违反了《上市公司信息披露管理办法》等相关规定，决定对发行人采取责令改正的行政监管措施，并要求发行人自收到决定书之日起30日内提交书面整改报告；对时任总经理李世锋、财务总监兼董事会秘书（代行）熊汉南采取出具警示函的行政监管措施。",
        "page_no": 3
      }
    },
    {
      "action_type": "warning_letter",
      "action_source_type": "regulator_required",
      "deadline": null,
      "required_disclosure": null,
      "evidence": {
        "evidence_text": "对时任总经理李世锋、财务总监兼董事会秘书（代行）熊汉南采取出具警示函的行政监管措施。",
        "page_no": 3
      }
    },
    {
      "action_type": "written_report_required",
      "action_source_type": "regulator_required",
      "deadline": "自收到决定书之日起30日内",
      "required_disclosure": null,
      "evidence": {
        "evidence_text": "要求发行人自收到决定书之日起30日内提交书面整改报告",
        "page_no": 3
      }
    },
    {
      "action_type": "rectification_required",
      "action_source_type": "company_committed",
      "deadline": null,
      "required_disclosure": null,
      "evidence": {
        "evidence_text": "发行人表示，高度重视决定书及监管函所指出的问题，将严格按照江西证监局和深圳证券交易所的要求，认真总结、积极整改并及时报送书面整改报告，进一步提高规范运作意识和财务管理水平，依法履行信息披露义务，提升信息披露质量。",
        "page_no": 4
      }
    }
  ],
  "source": {
    "url": "http://static.cninfo.com.cn/finalpage/2026-05-11/1225291749.PDF",
    "pdf_url": "http://static.cninfo.com.cn/finalpage/2026-05-11/1225291749.PDF"
  }
}

{
  "doc_id": "1225290815",
