  "regulator_name": {
    "value": "中国证券监督管理委员会江苏监管局",
    "evidence": {
      "evidence_text": "中国证券监督管理委员会江苏监管局（以下简称江苏证监局）",
      "page_no": 1
    }
  },
  "targets": [
    {
      "name": "江苏宝利国际投资股份有限公司",
      "role": null,
      "target_type": "listed_company",
      "evidence": {
        "evidence_text": "江苏宝利国际投资股份有限公司（以下简称公司）于2026 年5月11 日收到中国证券监督管理委员会江苏监管局（以下简称江苏证监局）出具的《关于对江苏宝利国际投资股份有限公司、周文彬、曹晔采取出具警示函措施的决定》",
        "page_no": 1
      }
    },
    {
      "name": "周文彬",
      "role": "时任董事长、总经理",
      "target_type": "director",
      "evidence": {
        "evidence_text": "公司时任董事长、总经理周文彬及时任董事会秘书曹晔未能勤勉地履行职责，违反了《信披办法》第四条的规定，对其任期内发生的信息披露违规行为承担主要责任。",
        "page_no": 1
      }
    },
    {
      "name": "曹晔",
      "role": "时任董事会秘书",
      "target_type": "executive",
      "evidence": {
        "evidence_text": "公司时任董事长、总经理周文彬及时任董事会秘书曹晔未能勤勉地履行职责，违反了《信披办法》第四条的规定，对其任期内发生的信息披露违规行为承担主要责任。",
        "page_no": 1
      }
    }
  ],
  "issues": [
    {
      "issue_type": "information_disclosure",
      "issue_summary": "公司发生多起诉讼、仲裁案件，未按规定及时履行信息披露义务，也未在相应定期报告中披露。",
      "is_violation_related": true,
      "evidence": {
        "evidence_text": "经查，2022 年3月至2025 年5月期间，江苏宝利国际投资股份有限公司（以下简称宝利国际或公司）发生多起诉讼、仲裁案件，公司未按规定及时履行信息披露义务，也未在相应的定期报告中披露。公司后续已补充披露相关信息。\n公司上述行为违反了《上市公司信息披露管理办法》（证监会令第182 号，以下简称《信披办法》）第三条第一款、第十四条第十项、第十五条第七项、第二十二条第一款及第二款第一项等规定。公司时任董事长、总经理周文彬及时任董事会秘书曹晔未能勤勉地履行职责，违反了《信披办法》第四条的规定，对其任期内发生的信息披露违规行为承担主要责任。",
        "page_no": 1
      }
    }
  ],
  "actions": [
    {
      "action_type": "warning_letter",
      "action_source_type": "regulator_required",
      "deadline": null,
      "required_disclosure": null,
      "evidence": {
        "evidence_text": "根据《信披办法》第五十二条的规定，我局决定对宝利国际、周文彬、曹晔采取出具警示函的行政监管措施，并记入证券期货市场诚信档案。",
        "page_no": 1
      }
    },
    {
      "action_type": "written_report_required",
      "action_source_type": "regulator_required",
      "deadline": "收到本决定书之日起10 个工作日内",
      "required_disclosure": null,
      "evidence": {
        "evidence_text": "你们应当于收到本决定书之日起10 个工作日内向我局报送书面报告。",
        "page_no": 1
      }
    },
    {
      "action_type": "rectification_required",
      "action_source_type": "company_committed",
      "deadline": null,
      "required_disclosure": null,
      "evidence": {
        "evidence_text": "公司及相关责任人高度重视《警示函》中所指出的问题，将认真吸取教训并引以为戒，积极进行整改，加强对《证券法》《上市公司信息披露管理办法》等相关法律法规、规范性文件的学习，不断提升规范运作水平。",
        "page_no": 2
      }
    }
  ],
  "source": {
    "url": "http://static.cninfo.com.cn/finalpage/2026-05-11/1225290815.PDF",
    "pdf_url": "http://static.cninfo.com.cn/finalpage/2026-05-11/1225290815.PDF"
  }
}

{
  "doc_id": "1225292102",
  "stock_code": "300005",
  "stock_name": "探路者",
  "market": "szse",
  "publish_date": "2026-05-11",
  "announcement_title": "探路者控股集团股份有限公司与国泰海通证券股份有限公司关于探路者控股集团股份有限公司向特定对象发行股票的审核问询函的回复",
  "doc_type": "reply",
  "regulator_name": null,
  "targets": [
    {
      "name": "探路者控股集团股份有限公司",
      "role": null,
      "target_type": "listed_company",
      "evidence": {
        "evidence_text": "探路者控股集团股份有限公司与国泰海通证券股份有限公司关于探路者控股集团股份有限公司向特定对象发行股票的审核问询函的回复",
        "page_no": null
      }
    },
    {
      "name": "国泰海通证券股份有限公司",
      "role": null,
      "target_type": "intermediary",
      "evidence": {
        "evidence_text": "探路者控股集团股份有限公司与国泰海通证券股份有限公司关于探路者控股集团股份有限公司向特定对象发行股票的审核问询函的回复",
        "page_no": null
      }
    },
    {
      "name": "北京通域众合科技发展中心（有限合伙）",
      "role": "控股股东",
      "target_type": "controlling_shareholder",
      "evidence": {
        "evidence_text": "发行人控股股东为北京通域众合科技发展中心（有限合伙）（以下简称通域众合）",
        "page_no": 4
      }
    },
    {
      "name": "李明",
      "role": "实际控制人",
      "target_type": "actual_controller",
      "evidence": {
        "evidence_text": "发行对象为发行人实际控制人李明控制的北京通域合盈投资管理有限公司（以下简称通域合盈）",
        "page_no": 4
      }
    }
  ],
  "issues": [
    {
      "issue_type": "raised_funds",
      "issue_summary": "本次募集资金用于补充流动资金的必要性及规模合理性、发行金额下限及认购数量下限",
      "is_violation_related": null,
      "evidence": {
        "evidence_text": "请发行人补充说明：（1）结合发行人资产负债率、在手资金、未来资金流入及资金支出安排等说明在持有较多闲置资金的情况下本次募集资金用于补充流动资金的必要性及规模合理性，未来大额资金支出安排是否已履行相关审议程序，是否具有必要性。（2）明确本次发行金额的下限及认购股票数量的下限，承诺的最低认购数量应与拟募集的资金金额相匹配。",
        "page_no": 4
      }
    },
    {
      "issue_type": "raised_funds",
      "issue_summary": "认购资金具体筹资安排、借款主体关系、偿债计划及股票质押或减持偿债对控制权稳定性的影响",
      "is_violation_related": null,
      "evidence": {
        "evidence_text": "（3）本次认购资金具体筹资安排，各借款主体的背景，与发行人及控股股东、实控人的关系，是否存在资金短缺的风险；各借款主体是否存在除借款协议之外的其他安排，是否存在对外募集、代持、结构化安排；本次认购资金借款是否有明确可行的偿债计划；是否存在将发行人股票质押用于本次认购及减持发行人股票用于偿还借款的情形或计划，如有，请说明是否对发行人控制权稳定性产生影响及发行人应对措施。",
        "page_no": 4
      }
    },
    {
      "issue_type": "internal_control",
      "issue_summary": "控股股东及实际控制人认定、控制权稳定性以及李明减持与不减持承诺",
      "is_violation_related": null,
      "evidence": {
        "evidence_text": "（4）结合发行人目前股权结构、董事会席位等说明控股股东及实际控制人的认定是否合理，发行人控制权是否稳定。（5）李明及其控制的主体在本次定价基准日前六个月是否存在减持其所持发行人股份的情形，是否已根据《上市公司收购管理办法》出具相关期限内不减持的承诺。",
        "page_no": 4
      }
    },
    {
      "issue_type": "other",
      "issue_summary": "发行方案调整、不同主体认购背景、明弘毅设立目的及锁定期规避风险",
      "is_violation_related": null,
      "evidence": {
        "evidence_text": "（6）发行人于2025 年10 月对本次发行方案进行调整的原因，通过不同主体参与本次发行认购的背景和原因，明弘毅是否专为本次发行而设立，后续对通域合盈和明弘毅持股结构安排及具体计划，是否存在规避锁定期限等相关要求的情形。",
        "page_no": 4
      }
    },
    {
      "issue_type": "raised_funds",
      "issue_summary": "前次募集资金用途变更用于永久补充流动资金的合规性",
      "is_violation_related": null,
      "evidence": {
        "evidence_text": "（7）发行人变更前次募集资金用途用于永久补充流动资金的具体情况，是否符合《证券期货法律适用意见第18 号》第五条的相关规定。",
        "page_no": 4
      }
    }
  ],
  "actions": [
    {
      "action_type": "inquiry_reply_required",
      "action_source_type": "regulator_required",
      "deadline": null,
      "required_disclosure": null,
